function applyFilters(){const sex=$('#sexFilter').value,age=$('#ageFilter').value,area=$('#areaFilter').value;let factor=1;if(sex==='Female')factor=.653;if(sex==='Male')factor=.347;if(age!=='All ages')factor*=({"< 30 years":.182,"30–44 years":.330,"45–59 years":.258,"60+ years":.230}[age]||1)*4;let total=area==='All health areas'?Math.round(527*factor):areaData[area].screened;total=Math.max(1,Math.min(area==='All health areas'?527:areaData[area].screened,total));const rate=area==='All health areas'?63:areaData[area].rate;const known=Math.round(total*.201),ref=Math.round(total*.368);$('[data-kpi="participants"]').textContent=total;$('[data-kpi="elevated"]').innerHTML=`${rate.toFixed(1)}<small>%</small>`;$('[data-kpi="known"]').innerHTML=`${(known/total*100).toFixed(1)}<small>%</small>`;$('[data-kpi="referral"]').innerHTML=`${(ref/total*100).toFixed(1)}<small>%</small>`;$('#selectedArea').textContent=area;$('#selectedAreaCopy').textContent=area==='All health areas'?'Select a point on the map to explore the area profile.':areaData[area].copy;$('#areaScreened').textContent=total;$('#areaRate').textContent=`${rate.toFixed(1)}%`;$$('.point').forEach(p=>p.classList.toggle('selected',p.dataset.area===area))}
