function esc(value){return String(value).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function projectPoint(lon,lat){return [200+(lon-8.49)*40,15+(13.1-lat)*32.5]}
function ringPath(ring){return ring.map((p,i)=>{const [x,y]=projectPoint(p[0],p[1]);return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`}).join(' ')+' Z'}
function featurePath(geometry){return geometry.type==='Polygon'?geometry.coordinates.map(ringPath).join(' '):geometry.coordinates.map(poly=>poly.map(ringPath).join(' ')).join(' ')}
async function renderRealMap(){const host=$('#realMap');if(!host)return;host.innerHTML='<div class="real-map-loading">Loading Cameroon administrative boundaries…</div>';try{const geo=await fetch('./public/cameroon-adm1.geojson').then(r=>r.json());const paths=geo.features.map(feature=>`<path class="region-shape" data-region="${esc(feature.properties.shapeName)}" d="${featurePath(feature.geometry)}" fill-rule="evenodd"><title>${esc(feature.properties.shapeName)} Region</title></path>`).join('');const pins=[['Molyko',9.30,4.16],['Buea Town',9.24,4.15],['Buea Road',9.27,4.13],['Bova',9.32,4.11]];const pinMarkup=pins.map(([name,lon,lat])=>{const [x,y]=projectPoint(lon,lat);return `<g class="area-pin-wrap" data-area="${name}"><circle class="area-pin" cx="${x}" cy="${y}" r="7"/><text x="${x+11}" y="${y+4}">${name}</text></g>`}).join('');host.innerHTML=`<svg viewBox="0 0 720 440" role="img" aria-label="Real Cameroon administrative region map"><g>${paths}</g>${pinMarkup}</svg>`;$$('.region-shape').forEach(region=>region.addEventListener('click',()=>{const name=region.dataset.region;$$('.region-shape').forEach(x=>x.classList.remove('selected'));region.classList.add('selected');$('#selectedArea').textContent=name+' Region';$('#selectedAreaCopy').textContent='Administrative region boundary from geoBoundaries ADM1. The screening brief does not provide regional totals.';$('#areaScreened').textContent='—';$('#areaRate').textContent='—';toast(`${name} Region selected`)}));$$('.area-pin-wrap').forEach(pin=>pin.addEventListener('click',()=>{const name=pin.dataset.area;$('#areaFilter').value=name;applyFilters();toast(`${name} selected`)}))}catch(error){host.innerHTML='<div class="real-map-loading">Unable to load the Cameroon boundary file.</div>';console.error(error)}}
