function renderOpenFreeMap(){const targets=[$('#realMap'),$('#standaloneMap')].filter(Boolean);if(!targets.length)return;if(!window.maplibregl){targets.forEach(renderLocalBoundaryFallback);return}window.healthyHeartsMaps=[];const locations=[{name:'Molyko',lat:4.1591154,lng:9.2805172},{name:'Buea Town',lat:4.1633434,lng:9.2384009}];targets.forEach(host=>{host.innerHTML='<div class="maplibre-canvas"></div><div class="google-map-overlay"><b>Southwest Cameroon</b><span>Free OpenStreetMap vector basemap</span><small>Verified: Molyko and Buea Town</small></div><div class="google-site-list"><button type="button" data-map-site="Molyko">Molyko</button><button type="button" data-map-site="Buea Town">Buea Town</button><span>OpenFreeMap · OpenStreetMap data</span></div>';const map=new maplibregl.Map({container:host.querySelector('.maplibre-canvas'),style:'https://tiles.openfreemap.org/styles/liberty',center:[9.26,4.16],zoom:12,attributionControl:true});map.addControl(new maplibregl.NavigationControl({showCompass:true}), 'top-right');map.on('load',()=>{fetch('./public/cameroon-adm1.geojson').then(response=>response.ok?response.json():null).then(geo=>{if(!geo)return;map.addSource('cameroon-adm1',{type:'geojson',data:geo});map.addLayer({id:'cameroon-adm1-lines',type:'line',source:'cameroon-adm1',paint:{'line-color':'#607d86','line-width':1.4,'line-opacity':.7}})}).catch(()=>{});locations.forEach(location=>{const el=document.createElement('button');el.className='maplibre-marker';el.type='button';el.title=location.name;el.innerHTML=`<span></span><b>${location.name}</b>`;el.addEventListener('click',()=>{$('#areaFilter').value=location.name;applyFilters();toast(`${location.name} selected`);map.flyTo({center:[location.lng,location.lat],zoom:15})});new maplibregl.Marker({element:el}).setLngLat([location.lng,location.lat]).addTo(map)})});host.querySelectorAll('[data-map-site]').forEach(button=>button.addEventListener('click',()=>{const location=locations.find(item=>item.name===button.dataset.mapSite);if(location){map.flyTo({center:[location.lng,location.lat],zoom:15});$('#areaFilter').value=location.name;applyFilters();toast(`${location.name} selected`)}}));window.healthyHeartsMaps.push(map)})}
