function updateInsights(){const bars=$$('#insightsView .bars > div');if(!bars.length)return;const sex=$('#sexFilter').value,age=$('#ageFilter').value,area=$('#areaFilter').value;let values=[37,23.1,35.3,4.6];if(sex==='Female')values=[41,23.5,31.1,4.4];if(sex==='Male')values=[29.5,22.4,43.2,4.9];const ageProfiles={'< 30 years':[66.7,20.8,10.0,2.5],'30–44 years':[44.3,29.3,22.0,4.4],'45–59 years':[16.2,22.8,52.0,9.0],'60+ years':[26.4,16.6,47.0,10.0]};if(sex==='All participants'&&ageProfiles[age])values=ageProfiles[age];if(area!=='All health areas'&&areaData[area]){const elevated=areaData[area].rate;const nationalNonElevated=[37,23.1,35.3,4.6];const nonElevated=100-elevated;const baseNonElevated=nationalNonElevated[0]+nationalNonElevated[1];values=[+(nonElevated*nationalNonElevated[0]/baseNonElevated).toFixed(1),+(nonElevated*nationalNonElevated[1]/baseNonElevated).toFixed(1),+(elevated*.88).toFixed(1),+(elevated*.12).toFixed(1)];const correction=+(100-values.reduce((sum,value)=>sum+value,0)).toFixed(1);values[0]=+(values[0]+correction).toFixed(1)}const labels=['Normal BP','Elevated BP','Hypertension range','Severely elevated'];bars.forEach((bar,index)=>{bar.querySelector('span').textContent=labels[index];bar.querySelector('b').textContent=`${values[index].toFixed(1)}%`;bar.querySelector('i').style.width=`${Math.max(0,Math.min(100,values[index]))}%`});const total=$('[data-kpi="participants"]')?.textContent||'527';const micro=$$('#insightsView .micro-label')[0];if(micro)micro.textContent=`N = ${total}`;const donut=$('#insightsView .donut strong');if(donut)donut.textContent=sex==='Female'?'65.3%':sex==='Male'?'34.7%':'65.3%';const donutLabel=$('#insightsView .donut small');if(donutLabel)donutLabel.textContent=sex==='Male'?'male':'female'}
