function updateInsights(){const bars=$$('#insightsView .bars > div');if(!bars.length)return;const sex=$('#sexFilter').value,age=$('#ageFilter').value,area=$('#areaFilter').value;const national=[37,23.1,35.3,4.6],sexProfiles={Female:[41,23.5,31.1,4.4],Male:[29.5,22.4,43.2,4.9]},ageProfiles={'< 30 years':[66.7,20.8,10,2.5],'30–44 years':[44.3,29.3,22,4.4],'45–59 years':[16.2,22.8,52,9],'60+ years':[26.4,16.6,47,10]};let values=sexProfiles[sex]||national;if(ageProfiles[age]){values=ageProfiles[age];if(sexProfiles[sex])values=values.map((value,index)=>value+(sexProfiles[sex][index]-national[index]));const sum=values.reduce((a,b)=>a+b,0);values=values.map(value=>value*100/sum)}if(area!=='All health areas'&&areaData[area]){let rate=areaData[area].rate;if(sex==='Female')rate-=4;if(sex==='Male')rate+=4;if(age==='< 30 years')rate-=5;if(age==='60+ years')rate+=5;rate=Math.max(0,Math.min(100,rate));const nonElevated=100-rate;values=[+(nonElevated*.616).toFixed(1),+(nonElevated*.384).toFixed(1),+(rate*.88).toFixed(1),+(rate*.12).toFixed(1)];values[0]=+(values[0]+(100-values.reduce((a,b)=>a+b,0))).toFixed(1)}const labels=['Normal BP','Elevated BP','Hypertension range','Severely elevated'];bars.forEach((bar,index)=>{bar.querySelector('span').textContent=labels[index];bar.querySelector('b').textContent=`${values[index].toFixed(1)}%`;bar.querySelector('i').style.width=`${Math.max(0,Math.min(100,values[index]))}%`});const total=$('[data-kpi="participants"]')?.textContent||'527';const micro=$$('#insightsView .micro-label')[0];if(micro)micro.textContent=`N = ${total}`;const donut=$('#insightsView .donut strong');if(donut)donut.textContent=sex==='Female'?'65.3%':sex==='Male'?'34.7%':'65.3%';const donutLabel=$('#insightsView .donut small');if(donutLabel)donutLabel.textContent=sex==='Male'?'male':'female';const ageRows=$$('#insightsView .age-list div');if(ageRows.length){const ageShares={'< 30 years':[100,0,0,0],'30–44 years':[0,100,0,0],'45–59 years':[0,0,100,0],'60+ years':[0,0,0,100]};const displayed=ageShares[age]||[18.2,33,25.8,23];ageRows.forEach((row,index)=>{row.querySelector('b').textContent=`${displayed[index].toFixed(1)}%`})}}
